package com.sami.app.sales;
import com.sami.app.common.exception.ApiException; import com.sami.app.sales.domain.SaleStatus; import com.sami.app.sales.service.SaleLifecycle; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class SaleLifecycleTest { @Test void supportsDocumentedLifecycle(){assertTrue(SaleLifecycle.allows(SaleStatus.DRAFT,SaleStatus.CONFIRMED));assertTrue(SaleLifecycle.allows(SaleStatus.CONFIRMED,SaleStatus.COMPLETED));assertTrue(SaleLifecycle.allows(SaleStatus.COMPLETED,SaleStatus.PARTIALLY_RETURNED));assertTrue(SaleLifecycle.allows(SaleStatus.PARTIALLY_RETURNED,SaleStatus.RETURNED));} @Test void terminalAndBackwardTransitionsFailClosed(){assertThrows(ApiException.class,()->SaleLifecycle.require(SaleStatus.CANCELLED,SaleStatus.DRAFT));assertThrows(ApiException.class,()->SaleLifecycle.require(SaleStatus.COMPLETED,SaleStatus.DRAFT));} }
